Algoritmo DiaSemana
  Definir dia Como Entero <- 6;
  Segun dia Hacer
    1, 2, 3, 4, 5:
      Escribir "Hay clase";
    6, 7:
      Escribir "Fin de semana";
    De Otro Modo:
      Escribir "Ese día no existe";
  FinSegun
FinAlgoritmo

Algoritmo Repetida
  Definir n Como Entero <- 1;
  Segun n Hacer
    1:
      Escribir "uno";
    1:
      Escribir "otra vez uno";
  FinSegun
FinAlgoritmo
